class Solution {
public:
    int minimumCost(int n, vector<vector<int>>& connections) {
        sort(connections.begin(), connections.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[2] < b[2];
        });
        vector<int> parent(n + 1);
        iota(parent.begin(), parent.end(), 0);

        auto find = [&](auto& self, int x) -> int {
            if (parent[x] != x) parent[x] = self(self, parent[x]);
            return parent[x];
        };

        int total_cost = 0;
        int components = n;
        for (const auto& c : connections) {
            int pu = find(find, c[0]), pv = find(find, c[1]);
            if (pu != pv) {
                parent[pu] = pv;
                total_cost += c[2];
                components--;
                if (components == 1) return total_cost;
            }
        }
        return components == 1 ? total_cost : -1;
    }
};

import java.util.*;

class Solution {
    int[] parent;

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public int minimumCost(int n, int[][] connections) {
        Arrays.sort(connections, (a, b) -> Integer.compare(a[2], b[2]));
        parent = new int[n + 1];
        for (int i = 0; i <= n; i++) parent[i] = i;

        int totalCost = 0;
        int components = n;
        for (int[] c : connections) {
            int pu = find(c[0]), pv = find(c[1]);
            if (pu != pv) {
                parent[pu] = pv;
                totalCost += c[2];
                components--;
                if (components == 1) return totalCost;
            }
        }
        return components == 1 ? totalCost : -1;
    }
}

var minimumCost = function(n, connections) {
    connections.sort((a, b) => a[2] - b[2]);
    const parent = Array.from({ length: n + 1 }, (_, i) => i);

    const find = (x) => {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    };

    let totalCost = 0;
    let components = n;
    for (const [u, v, cost] of connections) {
        const pu = find(u), pv = find(v);
        if (pu !== pv) {
            parent[pu] = pv;
            totalCost += cost;
            components--;
            if (components === 1) return totalCost;
        }
    }
    return components === 1 ? totalCost : -1;
};
